package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Account-synced RetroAchievements library and details. */
final class RetroDataView extends ScrollView {
 private final LinearLayout body,list;private final TextView status;private final EditText search;private final Map<String,String> coverCache=new HashMap<>();private JSONArray games=new JSONArray();private String user="";private final AccountRepository repo;
 RetroDataView(Context c){super(c);repo=new AccountRepository(c);body=new LinearLayout(c);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(16),dp(16),dp(16),dp(24));addView(body);body.addView(text("Meu Retrô",25));status=text("Sincronizando RetroAchievements…",13);body.addView(status);search=NativeSheet.input(c,"Buscar no Meu Retrô",160);body.addView(search);Spinner format=NativeSheet.options(c,new String[]{"Capas horizontais","Capas verticais"});format.setSelection(poster()?1:0);body.addView(format);format.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> parent){}public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){c.getSharedPreferences("batcaverna",0).edit().putBoolean("native_retro_poster",position==1).apply();render();}});Button add=button("＋ Adicionar do RetroAchievements");body.addView(add);add.setOnClickListener(v->catalog());Button cover=button("Alterar foto de capa");body.addView(cover);cover.setOnClickListener(v->((MainActivity)c).chooseStickerImage(uri->{status.setText("Salvando capa…");repo.uploadProfile(uri,"retro_cover",(rows,error)->{if(error!=null)status.setText(error);else load();});}));list=new LinearLayout(c);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int n,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render();}public void afterTextChanged(Editable e){}});load();}
 private void load(){repo.retro((rows,error)->{if(error!=null){status.setText(error);return;}JSONObject data=rows.optJSONObject(0),profile=data.optJSONObject("profile"),collection=data.optJSONObject("collection");user=data.optString("usuario");games=data.optJSONArray("jogos");status.setText(user+" · "+profile.optInt("pontos")+" pontos");android.view.View old=body.findViewWithTag("retroHero");if(old!=null)body.removeView(old);FrameLayout hero=new FrameLayout(getContext());hero.setTag("retroHero");ImageView bg=new ImageView(getContext());bg.setScaleType(ImageView.ScaleType.CENTER_CROP);hero.addView(bg,new FrameLayout.LayoutParams(-1,dp(160)));AccountImageLoader.load(bg,collection.optString("cover_url"));ImageView avatar=new ImageView(getContext());avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(dp(72),dp(72),android.view.Gravity.BOTTOM|android.view.Gravity.LEFT);lp.setMargins(dp(12),dp(12),dp(12),dp(12));hero.addView(avatar,lp);AccountImageLoader.load(avatar,profile.optString("avatar"));body.addView(hero,1,new LinearLayout.LayoutParams(-1,dp(160)));render();});}
 private void render(){list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);if(games==null)return;for(int i=0;i<games.length();i++){JSONObject game=games.optJSONObject(i);if(game==null||!game.optString("nome").toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout card=new LinearLayout(getContext());card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(12),dp(12),dp(12));ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(cover,new LinearLayout.LayoutParams(-1,dp(poster()?360:180)));rawgCover(game,cover);card.addView(text(game.optString("nome"),18));card.addView(text(game.optString("console")+" · "+game.optInt("desbloqueadas")+"/"+game.optInt("total")+" conquistas · "+game.optInt("hardcore")+" Hardcore",13));card.setBackground(AppStyle.shape(card,NativeTheme.panelDark(getContext()),16));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(12),0,0);list.addView(card,lp);card.setOnClickListener(v->details(game));}}
 private boolean poster(){return getContext().getSharedPreferences("batcaverna",0).getBoolean("native_retro_poster",false);}
 private void rawgCover(JSONObject game,ImageView image){String cacheKey=game.optString("nome")+":"+poster();String cached=coverCache.get(cacheKey);if(cached!=null){AccountImageLoader.load(image,cached);return;}AccountImageLoader.load(image,game.optString("capa"));if(poster()){try{repo.retroRequest(new JSONObject().put("op","capas").put("nomes",new JSONArray().put(game.optString("nome"))).put("format","poster"),(rows,error)->{if(error!=null||!image.isAttachedToWindow())return;JSONArray covers=rows.optJSONObject(0).optJSONArray("capas");String url=covers==null?"":covers.optString(0,"");if(!url.isEmpty()){coverCache.put(cacheKey,url);AccountImageLoader.load(image,url);}});}catch(JSONException ignored){}return;}repo.searchGames(game.optString("nome"),(rows,error)->{if(error!=null||!image.isAttachedToWindow())return;String wanted=key(game.optString("nome"));for(int i=0;i<rows.length();i++){JSONObject hit=rows.optJSONObject(i);if(hit!=null&&key(hit.optString("name")).equals(wanted)){String cover=hit.optString("background_image");coverCache.put(cacheKey,cover);AccountImageLoader.load(image,cover);break;}}});}
 private String key(String s){return java.text.Normalizer.normalize(s,java.text.Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 private void details(JSONObject game){NativeSheet sheet=new NativeSheet(getContext(),game.optString("nome"));ImageView cover=new ImageView(getContext());cover.setScaleType(ImageView.ScaleType.FIT_CENTER);sheet.body.addView(cover,new LinearLayout.LayoutParams(-1,dp(220)));rawgCover(game,cover);sheet.body.addView(text(game.optString("console"),15));Button achievements=button("Conquistas");sheet.body.addView(achievements);LinearLayout content=new LinearLayout(getContext());content.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(content);achievements.setOnClickListener(v->{achievements.setEnabled(false);content.removeAllViews();content.addView(text("Carregando conquistas…",13));request("raConquistas",game.optInt("gameId"),"",0,(rows,error)->{achievements.setEnabled(true);content.removeAllViews();if(error!=null){content.addView(text(error,14));return;}JSONArray list=rows.optJSONObject(0).optJSONArray("lista");for(int i=0;list!=null&&i<list.length();i++){JSONObject a=list.optJSONObject(i);if(a==null)continue;boolean earned=a.optBoolean("got",false);ImageView icon=new ImageView(getContext());icon.setContentDescription(a.optString("nome")+(earned?" — adquirida":" — não adquirida"));if(!earned){android.graphics.ColorMatrix gray=new android.graphics.ColorMatrix();gray.setSaturation(0f);icon.setColorFilter(new android.graphics.ColorMatrixColorFilter(gray));}else icon.clearColorFilter();content.addView(icon,new LinearLayout.LayoutParams(dp(48),dp(48)));AccountImageLoader.load(icon,a.optString("icon"));TextView title=text((earned?"✓ ":"")+a.optString("nome")+(a.optBoolean("hardcore")?" · Hardcore":""),16);title.setTextColor(earned?NativeTheme.accent(getContext()):0xffa6a6a6);content.addView(title);TextView description=text((earned?"Adquirida":"Não adquirida")+" · "+a.optString("desc")+" · "+a.optInt("pontos")+" pontos",13);if(!earned)description.setTextColor(0xffa6a6a6);content.addView(description);}});});sheet.show();}
 private void catalog(){NativeSheet sheet=new NativeSheet(getContext(),"Adicionar do RetroAchievements");String[] names={"Mega Drive","Nintendo 64","Super Nintendo","Game Boy","Game Boy Advance","Game Boy Color","NES","PlayStation","PlayStation 2","Nintendo DS","PSP","Dreamcast","Saturn","GameCube","Arcade"};int[] ids={1,2,3,4,5,6,7,11,21,18,41,40,39,78,27};Spinner platform=NativeSheet.options(getContext(),names);sheet.body.addView(platform);EditText query=NativeSheet.input(getContext(),"Nome do jogo",160);sheet.body.addView(query);Button find=button("Buscar");sheet.body.addView(find);LinearLayout results=new LinearLayout(getContext());results.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(results);find.setOnClickListener(v->{if(query.length()<2)return;find.setEnabled(false);results.removeAllViews();request("raSearch",0,query.getText().toString(),ids[platform.getSelectedItemPosition()],(rows,error)->{find.setEnabled(true);if(error!=null){results.addView(text(error,14));return;}JSONArray hits=rows.optJSONObject(0).optJSONArray("jogos");if(hits==null||hits.length()==0)results.addView(text("Nenhum jogo encontrado.",14));for(int i=0;hits!=null&&i<hits.length();i++){JSONObject g=hits.optJSONObject(i);LinearLayout result=new LinearLayout(getContext());result.setOrientation(LinearLayout.HORIZONTAL);result.setGravity(android.view.Gravity.CENTER_VERTICAL);ImageView picture=new ImageView(getContext());picture.setScaleType(ImageView.ScaleType.CENTER_CROP);result.addView(picture,new LinearLayout.LayoutParams(dp(poster()?80:140),dp(poster()?120:80)));Button add=button(g.optString("nome")+" · "+g.optString("console")+" · Adicionar");result.addView(add,new LinearLayout.LayoutParams(0,-2,1));results.addView(result);rawgCover(g,picture);add.setOnClickListener(w->{add.setEnabled(false);request("raSaveCollection",g.optInt("gameId"),"",0,(saved,err)->{if(err!=null){add.setEnabled(true);Toast.makeText(getContext(),err,Toast.LENGTH_LONG).show();}else{add.setText("✓ "+g.optString("nome"));load();}});});}});});sheet.show();}
 private void request(String op,int id,String query,int console,AccountRepository.Callback cb){try{JSONObject input=new JSONObject().put("op",op);if(id>0)input.put("gameId",id);if(op.equals("raConquistas"))input.put("usuario",user);if(op.equals("raSearch"))input.put("query",query).put("consoleId",console);repo.retroRequest(input,cb);}catch(JSONException e){cb.done(null,"Pedido inválido.");}}
 private Button button(String s){Button b=new Button(getContext());b.setText(s);AppStyle.button(b,false);return b;}
 private TextView text(String s,int size){return NativeSheet.text(getContext(),s,size,0xffeee8ff);}
 private int dp(int n){return NativeSheet.dp(getContext(),n);}
}
